const CACHE_PREFIX='process-design:'+new URL('./',self.location.href).pathname+':';
const CACHE=CACHE_PREFIX+'v17-source';
const ASSETS=['/','/index.html','/steam/','/steam/index.html','/ammonia/','/ammonia/index.html','/style.css','/shell.js','/app.js','/units.mjs','/history.mjs','/report.mjs','/engine/worker.mjs','/engine/thermo.mjs','/engine/coolprop.js','/engine/coolprop.wasm','/engine/LICENSE-CoolProp.txt','/ammonia/app.js','/ammonia/calc.js','/ammonia/data.js','/ammonia/history.js','/manifest.webmanifest','/icon.svg','/icons/icon-192.png','/icons/icon-512.png','/icons/maskable-512.png','/icons/apple-touch-icon.png'].map(path=>new URL('.'+path,self.location.href).pathname);
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll(ASSETS);await self.skipWaiting();})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith(CACHE_PREFIX)&&key!==CACHE)await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;if(!ASSETS.includes(url.pathname))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);const cached=await cache.match(url.pathname);return cached||fetch(event.request);})());});
